Return JSON with these keys: vendor_name, invoice_number, invoice_date (YYYY-MM-DD), amount (number), is_credit (true or false), job_hint (any job name, property address, PO number or claim number printed on the invoice, empty string when there is none), confidence (0 to 1, how sure you are of the fields you filled).

parameters.jsCode:
// One pass per invoice: find the AccuLynx job, then make sure this invoice has not been through here before.
const inv = $('Pull out vendor, number, date and amount').first().json.message.content;
const rows = $('Check your job list and what is already entered').all().map(i => i.json);

const jobs = rows.filter(r => String(r.Type).toLowerCase() === 'job');
const entered = rows.filter(r => String(r.Type).toLowerCase() === 'invoice');

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const key = norm(inv.vendor_name) + '|' + norm(inv.invoice_number);

// Duplicates are checked on a stable key, plus amount and date for vendors who reuse invoice numbers.
const duplicate = entered.find(r =>
  (norm(r.Vendor) + '|' + norm(r.InvoiceNumber)) === key ||
  (norm(r.Vendor) === norm(inv.vendor_name) && Number(r.Amount) === Number(inv.amount) && r.InvoiceDate === inv.invoice_date)
);

// Job match runs on whatever the invoice prints: job name, property address, PO or claim number.
const hint = norm(inv.job_hint);
let match = null, best = 0, runnerUp = null;
for (const j of jobs) {
  for (const f of [j.JobName, j.Address, j.PONumber, j.ClaimNumber].map(norm)) {
    if (!f || !hint) continue;
    if ((hint.includes(f) || f.includes(hint)) && f.length > best) { runnerUp = match; best = f.length; match = j; }
  }
}

const confident = !duplicate && match && best >= 8 && (inv.confidence ?? 0) >= 0.7;
const reason = duplicate
  ? 'Looks like a duplicate of invoice ' + duplicate.InvoiceNumber + ' already entered on ' + duplicate.JobName
  : !match
    ? 'Nothing on the job list matches "' + (inv.job_hint || 'no job reference printed on the invoice') + '"'
    : !confident
      ? 'Weak match to ' + match.JobName + (runnerUp ? ', could also be ' + runnerUp.JobName : '')
      : '';

// [PLACEHOLDER] your naming convention. Send me one example filename and I swap the order here.
const filename = [inv.invoice_date, inv.vendor_name, inv.invoice_number]
  .filter(Boolean).join('_').replace(/[^\w.-]/g, '-') + '.pdf';

return [{ json: { ...inv, job_id: match ? match.JobID : '', job_name: match ? match.JobName : '', confident, duplicate: Boolean(duplicate), reason, filename } }];

// Reconciliation is arithmetic, not a language job, so this runs in code and gives the same answer every time.
const form = $('You drop in a vendor statement').first().json;
const entered = $input.all().map(i => i.json);

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const money = s => Number(String(s).replace(/[^0-9.-]/g, '')) || 0;

// Each pasted line: invoice number, date, amount. Credits come through negative or marked CR.
const lines = String(form['Statement lines']).split('\n').map(l => l.trim()).filter(Boolean).map(l => {
  const parts = l.split(/[,\t;]+/).map(p => p.trim());
  const amount = money(parts[parts.length - 1]);
  return { raw: l, number: parts[0], date: parts[1] || '', amount, is_credit: /cr|credit/i.test(l) || amount < 0 };
});

const findings = [];
let accounted = 0;

for (const line of lines) {
  const hits = entered.filter(r => norm(r.InvoiceNumber) === norm(line.number));
  if (hits.length === 0) {
    findings.push({ issue: line.is_credit ? 'Missing credit' : 'Missing invoice', invoice: line.number, statement_amount: line.amount, note: 'On the statement, not in AccuLynx' });
  } else if (hits.length > 1) {
    findings.push({ issue: 'Duplicate invoice', invoice: line.number, statement_amount: line.amount, note: 'Entered ' + hits.length + ' times, on ' + hits.map(h => h.JobName).join(' and ') });
  } else if (Math.abs(money(hits[0].Amount) - line.amount) > 0.01) {
    findings.push({ issue: 'Incorrect amount', invoice: line.number, statement_amount: line.amount, note: 'AccuLynx has ' + hits[0].Amount });
  } else if (!hits[0].JobName) {
    findings.push({ issue: 'Not matched to a job', invoice: line.number, statement_amount: line.amount, note: 'Entered but sitting without a job' });
  } else {
    accounted += 1;
  }
}

const lineTotal = lines.reduce((a, l) => a + l.amount, 0);
const stated = money(form['Statement total']);
if (stated && Math.abs(stated - lineTotal) > 0.01) {
  findings.push({ issue: 'Statement does not reconcile', invoice: '', statement_amount: stated, note: 'Lines add up to ' + lineTotal.toFixed(2) });
}

return [{ json: {
  vendor: form.Vendor,
  month: form['Statement month'] || '',
  lines_on_statement: lines.length,
  accounted_for: accounted,
  findings,
  clear_to_pay: findings.length === 0,
  summary: findings.length === 0
    ? 'All ' + lines.length + ' lines are in AccuLynx on the right jobs.'
    : accounted + ' of ' + lines.length + ' lines check out. ' + findings.length + ' need a look before you pay.'
} }];

